// W5c (section 3 pick A), welltest beginner: the OBODO-4 buildup.
//
// The Associate capstone graded the bundled buildup fixture, which the buildup
// explorer opened on. It moves to OBODO-4: a buildup generated here by the
// vendored engine's own exact superposition of the homogeneous model with
// storage and skin (evaluateBuildup), written as a text file of shut-in times
// and pressures that the learner downloads from the capstone card and opens in
// the buildup explorer's "Your test" mode. The keys are regenerated by parsing
// that file and running the panel lab (buildupWindowFor), which calls the
// vendored Horner analysis. Nothing here computes a graded value itself.
import { getModel, evaluateBuildup } from '../../../../packages/engines/engines/welltest/models/modelCatalog.js';
import { buildupWindowFor, parseBuildupText } from '../../../../src/components/course/panels/welltest/welltestLab.js';

export const RESERVOIR = { phi: 0.21, mu: 1.3, ct: 1.1e-5, rw: 0.3, h: 62, B: 1.18, q: 620, pi: 5200 };
export const PLANT = { k: 42, skin: 3.2, C: 0.02 };
export const TP = 48;
export const MIN_DT = 8;

export function build() {
  const dts = Array.from({ length: 40 }, (_, i) => 0.01 * 10 ** (i / 10));
  const pts = evaluateBuildup({ model: getModel('homogeneous'), params: PLANT, reservoir: RESERVOIR, tp: TP, dts });
  const pwf = Math.round(pts.pwfAtShutIn * 1000) / 1000;
  const lines = ['# OBODO-4 pressure buildup after 48 h at 620 stb/d', '# shut-in time dt (h), shut-in pressure pws (psia)', 'dt_h,pws_psia'];
  for (const p of pts) lines.push(`${p.dt.toFixed(6)},${p.pws.toFixed(3)}`);
  return { text: lines.join('\n') + '\n', pwfShutIn: pwf };
}

export function gradedKeys(text = build().text, pwfShutIn = build().pwfShutIn) {
  const fit = buildupWindowFor({ points: parseBuildupText(text), tp: TP, pwfShutIn, reservoir: RESERVOIR }, MIN_DT);
  return {
    beginner: [
      { key: 'obodo_horner_k_md', tol: 0.05, unit: 'mD', label: 'OBODO-4 Horner permeability', expected: fit.k },
      { key: 'obodo_horner_skin', tol: 0.005, unit: '-', label: 'OBODO-4 skin from the one-hour pressure', expected: fit.skin },
      { key: 'obodo_slope_psi_cycle', tol: 0.005, unit: 'psi/cycle', label: 'OBODO-4 semilog slope', expected: fit.m },
      { key: 'obodo_pstar_psia', tol: 0.05, unit: 'psia', label: 'OBODO-4 extrapolated pressure p star', expected: fit.pStar },
      { key: 'obodo_skin_dp_psi', tol: 0.05, unit: 'psi', label: 'OBODO-4 skin pressure drop', expected: fit.dpSkin },
      { key: 'obodo_ri_at_tp_ft', tol: 0.5, unit: 'ft', label: 'OBODO-4 radius of investigation at 48 h', expected: fit.riAtTp },
    ],
    n: fit.n,
  };
}
